-- Veelbelovende en experimentele trainingsmethodes (docs/trainingsmethodes-
-- onderzoek-2026-10-16.md): een label op workouts, en negen workouts in de
-- bibliotheek.
--
-- method_label staat op de bibliotheek én op de geplande workout. Een workout uit
-- de bibliotheek neemt het label mee (addWorkoutFromTemplate); een AI-workout
-- krijgt het van de generator (methodLabel in de uitvoer). Leeg betekent: een
-- gewone trainingsvorm. Het label gaat ook vooraan in de beschrijving naar
-- intervals.icu, zodat het lid het in Zwift ziet.
--
-- "VO2max 30/15 blokweek" gebruikt onOff in structure_json: één blok van
-- 9 minuten is 12 x (30 s op het doel + 15 s op offTarget). Zie
-- WorkoutBlock.onOff in src/lib/training/workouts.ts.
--
-- De sweet-spotblokken liggen op 87-89%: in de studie RPE 14-15, 66% van het
-- VO2max-vermogen en 85% van de maximale hartslag. De drie minuten herstel
-- ertussen zijn een eigen keuze; de studie noemt ze niet in de samenvatting.

alter table public.training_workout_templates
  add column if not exists method_label text
    check (method_label in ('veelbelovend', 'experimenteel'));

alter table public.training_workouts
  add column if not exists method_label text
    check (method_label in ('veelbelovend', 'experimenteel'));

insert into public.training_workout_templates
  (form, title, description, duration_minutes, intensity, target_type, structure_json, method_label, is_standard)
select
  v.form, v.title, v.description, v.duration_minutes, v.intensity, v.target_type, v.structure_json, v.method_label, true
